    public List<DatedSetting> getSettings() {
        return settings.stream()
                .sorted(Comparator.comparing(DatedSetting::getKey)
                        .thenComparing(DatedSetting::getFrom, Comparator.nullsFirst(Comparator.naturalOrder())))
                .toList();
